// Household deprivation from the 2021 census, with no runtime imports so
// data_processing scripts running in Node can share it with the browser.
//
// The census counts each household as deprived in 0 to 4 "dimensions":
// employment, education, health & disability, and housing.

/** Households deprived in 0, 1, 2, 3 and 4 dimensions */
export type HouseholdDeprivation = [number, number, number, number, number];

/** LSOA_2021_deprivation.json, generated by data_processing/scripts/deprivation_maker.mjs */
export interface DeprivationData {
    source: string;
    dimensions: string[];
    categories: string[];
    lsoa: Record<string, HouseholdDeprivation>;
}

/**
 * Deprivation score: the average number of dimensions a household in the area is deprived in.
 * 0 means no household is deprived at all; 4 would mean every household is deprived in all four.
 * In practice areas range from about 0.1 to 1.5.
 *
 * It uses every category (unlike "share deprived in at least one dimension"),
 * so an area where many households are deprived in several ways scores higher
 * than one where they are each deprived in just one.
 */
export function deprivation_score(households: HouseholdDeprivation): number {
    let total_households = 0;
    let total_dimensions = 0;

    households.forEach((count, dimensions) => {
        total_households += count;
        total_dimensions += count * dimensions;
    });

    return total_households > 0 ? total_dimensions / total_households : NaN;
}
